        if len(arr) == 1:
            return arr[0]
        pivot = helper1(arr)
        left, middle, right = helper2(arr, pivot)
        if k <= len(left):
            return select(left, k)
        elif k <= len(left) + len(middle):
            return middle[0]
        else:
            return select(right, k - len(left) - len(middle))

    return select(nums, k)
