def solve(intervals):
    if not intervals:
        return 0

    # Sort intervals by end time
    intervals.sort(key=lambda x: x[1])

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i):
        if i >= len(intervals):
            return 0
        # Option 1: skip current interval
        skip = dp(i + 1)
        # Option 2: take current interval, find next non-overlapping interval
        next_idx = i + 1
        while next_idx < len(intervals) and intervals[next_idx][0] < intervals[i][1]:
            next_idx += 1
        take = 1 + dp(next_idx)
        return max(skip, take)

    return len(intervals) - dp(0)
