def solve(n):
    def fib(n, var1):
        if n in var1:
            return var1[n]
        if n == 0:
            return 0
        if n == 1:
            return 1
        result = fib(n - 1, var1) + fib(n - 2, var1)
        var1[n] = result
        return result

