Here is a correct solution to this task:

```python
def solve(nums, target):
    def helper1(nums, target):
        left, right = 0, len(nums) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                right = mid - 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    def helper2(nums, target):
        left, right = 0, len(nums) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    if not nums:
        return [-1, -1]

    n = len(nums)
    if nums[0] == target:
        first = 0
    else:
        first = 1
        while first < n and nums[first] < target:
            first *= 2

    left = first // 2
    right = min(first, n - 1)
    first_index = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            first_index = mid
            right = mid - 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    if first_index == -1:
        return [-1, -1]

    # Find last occurrence
    left = first_index
    right = n - 1
    last_index = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            last_index = mid
            left = mid + 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return [first_index, last_index]
